mobile-android-segmented-button--default.snippet:
import { Component } from '@angular/core';
import { AndroidSegmentedButtonComponent } from './android-segmented-button.component';

@Component({
  selector: 'app-demo',
  imports: [AndroidSegmentedButtonComponent],
  template: `
    <div class="p-4">
        <app-android-segmented-button
            [options]="options"
            [(value)]="value"
            [ariaLabel]="ariaLabel" />
    </div>`,
})
export class DemoComponent {
  options = ['Day', 'Week', 'Month'];
  value = 'Week';
  ariaLabel = 'Range';
  valueChange(event: unknown) {}
}

